import java.util.*;

class Solution {
    public boolean canSplitEvenly(int[] w) {
        int total = 0;
        for (int x : w) total += x;
        if (total % 2 != 0) return false;            // odd total can't be halved
        int half = total / 2;
        boolean[] ok = new boolean[half + 1];        // ok[c] = some items weigh exactly c
        ok[0] = true;
        for (int x : w) {
            for (int c = half; c >= x; c--) {        // downward: each item used once
                if (ok[c - x]) ok[c] = true;
            }
        }
        return ok[half];
    }
}

