class Solution:
    def canSplitEvenly(self, w: List[int]) -> bool:
        s = sum(w)
        if s % 2: return False
        half = s // 2
        ok = [True] + [False] * half
        for x in w:
            for c in range(half, x - 1, -1):
                if ok[c - x]: ok[c] = True
        return ok[half]

