function canSplitEvenly(w) {
  const s = w.reduce((a, b) => a + b, 0);
  if (s % 2) return false;
  let reach = new Set([0]);
  for (const x of w) { const nx = new Set(reach); for (const v of reach) if (v + x <= s / 2) nx.add(v + x); reach = nx; }
  return reach.has(s / 2);
}
